    faq: [{"q":"被リンクは購入しても大丈夫ですか？","a":"いいえ、Googleのガイドラインで禁止されており、ペナルティの対象になります。購入リンクは効果が薄いだけでなく、検索順位を下げるリスクがあります。"},{"q":"被リンクが増えない原因は何ですか？","a":"コンテンツがリンクする価値に欠ける、アウトリーチ不足、業界内での認知度が低いなどが主な原因です。まずは独自データや網羅的な記事を作り、積極的にアプローチしましょう。"},{"q":"被リンクの質を見分ける方法は？","a":"リンク元の関連性、ドメインオーソリティ、スパムスコア、リンクの位置（本文中かサイドバーか）などをチェックします。関連性の高いサイトからの本文中リンクが最も価値があります。"},{"q":"被リンクは何本あれば効果が出ますか？","a":"本数ではなく質が重要です。高品質な被リンクが数本あれば、低品質なリンク100本より効果的な場合があります。競合サイトの被リンクプロフィールを分析して目安を把握しましょう。"}],
