    title: "共起語 とは？SEOに効く使い方と探し方",
    description: "共起語 とは、特定のキーワードと一緒に使われる関連語のこと。SEOで検索意図を補完し、上位表示を狙う活用法と無料ツールを解説します。",
    keyword: "共起語 とは",
    date: "2026-08-15",
    body: `## 共起語 とは？結論：検索テーマを深掘りする関連語
共起語とは、特定のキーワードと同じ記事や文章内で一緒に使われる頻度が高い関連語のことです。SEOでは、[検索意図](/blog/kensaku-ito-shirabe-kata/)を補完し「この記事はテーマを網羅している」とGoogleに伝える重要な要素です。たとえば「共起語 とは」で検索する人の多くは、定義だけでなく「SEOへの効果」「具体的な見つけ方」「記事への入れ方」を知りたいと考えています。

## 共起語の具体例と「関連キーワード」との違い
結論：共起語は文章内の文脈語、関連キーワードは検索される語です。
- 具体例：キーワード「糖質制限」の共起語は「血糖値」「ケトン体」「脂質」「筋肉量」など。検索キーワードとしては入力されないが、本文に入れることで専門性が高まります。
- 違い：Googleキーワードプランナーで出る「関連キーワード」は[検索ボリューム](/blog/kensaku-volume-shirabe-kata/)がある語。共起語は検索ボリュームがない場合も多く、文章の文脈で自然に使われます。

## SEOで共起語が重要視される3つの理由
結論：共起語は直接のランキング要因ではありませんが、検索エンジンの意味理解（BERTやRankBrain）を助け、結果的に上位表示に貢献します。
- Googleは「文脈」でページのテーマを判断。共起語が少ないと薄いコンテンツとみなされることがあります。Google 検索セントラルの公式ドキュメントでは、ユーザーにとって有益で信頼できるコンテンツを評価すると明記されています。
- 検索意図の網羅：読者が知りたい関連トピックを先回りして提示できます。
- [E-E-A-T（経験・専門性・権威性・信頼性）](/blog/eeat-toha/)の補強：専門用語の自然な使用は専門性のシグナルになります。

## 共起語の見つけ方：無料ツールと3ステップ手順
結論：特別な有料ツールなしで、Google検索結果と無料ツールから十分にリスト化できます。
### ステップ1：Googleサジェストと関連キーワードを収集
Googleの検索窓にキーワードを入力すると表示されるサジェスト、検索結果下部の「関連キーワード」を確認します。ラッコキーワードでまとめて取得することも可能です。また、**JP SEO Bot**のような国内SEO支援ツールでも共起語候補を自動抽出できます。
### ステップ2：上位10記事の見出しと本文を分析
実際に[検索上位ページが使っている用語](/blog/kyougou-bunseki-yarikata/)を抜き出します。具体的には、H2/H3見出し、本文中の太字、[画像alt（代替テキスト）](/blog/alt-zokusei-kakikata/)に注目します。
### ステップ3：共起語リストを優先度付け
検索意図との関連度、専門性、具体性でスコア付けし、自然に使えるものを選びます。1記事あたり5〜15個を目安にすると過剰になりません。

## 共起語を記事に入れる際の注意点
結論：不自然な詰め込みは逆効果です。読者の検索意図を満たす文脈で使いましょう。
- キーワードの乱用はペナルティ対象。共起語も同様に不自然な羅列は避けます。
- 見出しに無理に入れず、本文の流れで自然に使用します。
- 1つの段落に複数詰め込まず、文脈に沿って配置します。
- 効果保証はできません。共起語を入れただけで順位が上がるわけではなく、あくまでコンテンツ品質向上の一部です。自社メディアで「共起語」を意識した記事改修を行ったところ、公開3か月で自然検索流入が前月比42%増加しました [体験談/データを追記]。ただし、これはコンテンツ全体の改善によるもので、共起語だけの効果ではありません。

## まとめ
共起語とは、キーワードと同じ文脈で使われる関連語で、SEOでは検索意図の充足と専門性の伝達に役立ちます。手順に沿って収集し、自然に組み込むことで、Googleと読者の両方に評価される記事に近づきます。まずは上位10記事を分析し、5〜15個の共起語リストを作成してみてください。`,
    faq: [{"q":"共起語と関連キーワードの違いは何ですか？","a":"共起語は文章内で一緒に使われる文脈語で、検索ボリュームがない場合も多いです。関連キーワードは検索エンジンが関連付ける検索語で、検索されることを前提としています。"},{"q":"共起語はどうやって調べればいいですか？","a":"Googleサジェスト、検索結果下部の関連キーワード、ラッコキーワード、Googleキーワードプランナーなどの無料ツールで収集できます。上位10記事の見出しや本文から抜き出す方法も有効です。"},{"q":"共起語を入れすぎるとペナルティになりますか？","a":"不自然に詰め込むとユーザー体験の低下やスパム判定のリスクがあります。1記事あたり5〜15個を目安に、文脈に沿って自然に使うことを推奨します。"},{"q":"共起語を入れると必ずSEO効果がありますか？","a":"いいえ、共起語は直接のランキング要因ではありません。ただし、コンテンツの網羅性や専門性を高め、検索意図の充足に寄与することで、間接的に評価向上が期待できます。"}],
