    faq: [{"q":"AI文章 検出ツールは無料で使えますか？","a":"はい、GPTZeroやCopyleaksなど一部は無料枠があります。ただし無料版は文字数制限や機能制限があり、精度検証には有料版が必要な場合があります。"},{"q":"検出ツールのスコアが高い場合、必ずAIが書いたのでしょうか？","a":"いいえ。人間が書いた文章でもスコアが高く出る「偽陽性」が一定数あります。特に箇条書きや専門用語が多い文章は誤判定されやすいため、スコアだけで判断しないでください。"},{"q":"GoogleはAI生成コンテンツをペナルティ対象にしていますか？","a":"GoogleはAI生成かどうかではなく、コンテンツの品質と独自性を評価します。品質が高く、ユーザーに価値を提供するAI生成コンテンツはスパムポリシーに違反しません。"},{"q":"日本語の文章でも検出ツールは有効ですか？","a":"英語に比べると精度は低く、誤判定が起きやすいのが現状です。日本語対応を謳うツールでも、文種や文体によってスコアが大きくばらつくため、参考値として使うのがおすすめです。"},{"q":"検出ツールのスコアを下げるコツはありますか？","a":"箇条書きを減らす、一文の長さに変化をつける、具体例や体験談を入れるなどの工夫でスコアが下がることがあります。ただし、不自然に下げようとすると文章品質が落ちるため注意が必要です。"}],
