    body: `## 結論：AI記事構成は検索意図の分解から始める
AIに記事構成を作らせる際、最初に検索意図を明確に分解し、見出しごとの役割を指示すれば、検索上位を狙える構成を効率的に作成できます。本記事では、検索意図から見出しを導かせる指示の出し方と、構成レビューの観点を具体的に解説します。

## 検索意図を分解する3ステップ
検索意図の分解は、AIに指示を出す前の準備段階として最も重要です。以下の3ステップを踏むことで、AIが的外れな見出しを出すリスクを減らせます。
- ステップ1：検索クエリを4タイプ（Know/Do/Go/Buy）に分類する。今回の「AI 記事構成」はKnow（情報収集）タイプで、ノウハウを知りたいユーザーが多いと想定します。
- ステップ2：Googleサジェストや関連キーワード（例：AI 記事構成 プロンプト、AI 記事構成 作り方）から、ユーザーが抱える具体的な悩みを抽出します。
- ステップ3：抽出した悩みを「結論→理由→具体例」の順に並べ、見出し候補を整理します。この段階でAIに渡す情報が精度を左右します。

## AIに指示を出すときのプロンプト実例
AIに記事構成を依頼する際は、検索意図の分解結果をプロンプトに含めることが必須です。以下は実践的なプロンプト例です。
「あなたはSEO記事構成の専門家です。キーワード『AI 記事構成』で検索するユーザーの検索意図を分解し、H2見出しを3〜5個提案してください。各見出しには『結論→理由→具体例』を含め、具体的な数値や手順、公的機関の情報を入れてください。また、共起語として『SEO対策』『検索意図』『構成案』を含めてください。」
このように、ゴールと制約を明示することで、AIは検索意図を満たす構成案を出しやすくなります。

## 構成レビューで必ずチェックすべき5つの観点
AIが生成した構成案は、そのまま公開せず必ず人間がレビューします。以下5つの観点で確認してください。
- 検索意図との一致：各H2見出しがユーザーの知りたいことに直接答えているか。Knowタイプならノウハウの提供が最優先です。
- 見出しの階層構造：H2は3〜5個、H3は内容を分割しすぎず、1つのH2に対して1〜2個が適切です。
- E-E-A-Tの裏付け：経験・専門性・権威性・信頼性を示す情報が本文中に含まれているか。Google品質評価ガイドラインではこれらが重要視されます。
- 具体性の確保：数字・手順・固有名詞が2〜3点入っているか。例えば、Google検索セントラル公式ブログやYahoo! JAPAN検索の仕様に言及すると説得力が増します。
- 実測データとの照合：公開後、Search ConsoleのCTRや平均掲載順位を確認し、意図とズレた見出しを修正します。[体験談/データを追記]
なお、構成レビューには **JP SEO Bot** のようなSEOチェックツールで網羅性を確認するのも有効ですが、最終判断は必ず人間が行ってください。

## まとめ
AI記事構成の質は、検索意図をどれだけ分解して指示に落とし込めるかで決まります。Knowタイプの検索意図を分解し、AIにH2見出しを3〜5個提案させ、人間が5つの観点でレビューする。この一連の流れを回せば、検索上位を狙える記事構成を継続的に生み出せます。まずは本記事のプロンプト例をそのまま使い、自社のデータで改善を重ねてください。`,
    faq: [{"q":"AIに記事構成を任せる際、最初に何を指示すればよいですか？","a":"検索意図の分解を指示してください。キーワードの4タイプ分類、サジェスト抽出、見出し案の提示をAIに求めると、精度が上がります。"},{"q":"AIが作った記事構成のレビューで最も重要な観点は何ですか？","a":"検索意図との一致です。見出しがユーザーの検索意図を網羅し、結論→理由→具体例の流れになっているかを確認します。"},{"q":"AIに指示するプロンプトの具体例を教えてください。","a":"「キーワード『AI 記事構成』で検索するユーザーの悩みを分解し、H2見出しを3〜5個提案してください。各見出しには具体的な数字や手順を含めてください」と指示します。"},{"q":"AIで作った構成を公開前にチェックするツールはありますか？","a":"JP SEO BotなどのSEOチェックツールで、キーワード網羅性や共起語の含まれ方を確認できます。ただし最終判断は人間が行ってください。"},{"q":"記事構成で検索上位を狙うために、文字数や見出し数の目安はありますか？","a":"目安として本文は2000〜3000文字、H2は3〜5個、H3は各H2に対して1〜2個が適切です。ただし検索意図を満たすことが最優先です。"}],
