    title: "DeepSeekの安全性は？データ扱いと社内利用の論点",
    description: "DeepSeekの安全性をデータ保存場所・利用規約・社内利用のチェックポイントから解説。個人情報保護法に配慮した運用方法を提示します。",
    keyword: "DeepSeek 安全性",
    date: "2026-08-26",
    body: `## 結論：DeepSeekの安全性は「利用方法」で決まる

DeepSeekは個人の通常利用であれば他社製生成AIと同程度の注意で安全に使えますが、企業利用ではデータの保存場所と利用規約の確認が必須です。特に日本の個人情報保護法では、中国国内サーバーへの個人データ移転が論点になるため、機密情報や顧客情報をそのまま入力しない運用が大前提です。

## データの扱い：保存場所と収集項目を確認

DeepSeekの公式プライバシーポリシーでは、収集した情報は中華人民共和国にあるサーバーに保存されると明記されています。また、アカウント情報・端末情報・利用履歴・入力内容などが収集対象です。入力したテキストはモデル改善に利用される可能性があります。

- 保存場所：中国国内サーバー（日本からは越境移転）
- 収集項目：氏名・メールアドレス・IPアドレス・入力プロンプト・チャット履歴など
- 削除リクエスト：一部の国では個人情報の削除を請求可能（ただし完全削除は保証されない）

**結論：** 業務上の秘密情報や個人情報を入力しないことが最も確実な防御策です。

## 利用規約：入力データの利用範囲とオプトアウト

DeepSeekの利用規約では、ユーザーが入力したデータをサービス向上やモデル学習に利用する権利が事業者に付与される規定があります。ただし、Web版やアプリでは「モデル改善へのデータ利用」をオフにする設定が提供されている場合があります。

- 利用前に必ず「設定」→「データ管理」等の項目を確認（UIは変更されることがあります）
- オプトアウト設定があれば、業務利用前に必ず有効化
- 無料版とAPI版ではデータの取り扱いが異なるため、契約書類を確認

**結論：** 無料版は利便性と引き換えにデータ利用の許諾が広い傾向があります。企業ではAPI契約などでデータ非利用を明記することが推奨されます。

## 社内利用時に確認すべき論点

企業でDeepSeekを導入・試用する場合、以下の点を事前に整理する必要があります。特に日本の個人情報保護法第28条では、外国にある第三者へ個人データを提供する際、本人の同意または同等の措置が求められます。

- 利用目的の限定：業務で使うデータの種類と入力禁止項目を明確化
- アカウント管理：個人アカウントで業務データを扱わない（共有アカウント禁止）
- 保存先の確認：データが日本国外サーバーに保存されることを前提としたリスク評価
- 契約上の保護：可能であればAPI利用契約に「学習利用禁止」「秘密保持」「データ削除」を盛り込む
- 社内教育：生成AI全般のリテラシー教育と併せて、DeepSeek特有の注意点を周知



## まとめ

DeepSeekの安全性は、個人の通常利用では大きな問題はありませんが、企業利用ではデータ保存場所と利用規約の確認が不可欠です。機密情報や個人情報を入力しない運用を徹底し、可能ならAPI契約でデータ非利用を担保するのが現実的な対策です。社内ルールを文書化する際は、**JP SEO Bot** などの社内FAQツールに反映すると確認漏れを防げます。`,
    faq: [{"q":"DeepSeekは安全に使えますか？","a":"個人で一般的な利用をする分には、他社製AIと同等の注意で問題ありません。ただし、個人情報や機密情報を入力しないことが前提です。企業利用ではデータ保存場所と利用規約の確認が必要です。"},{"q":"DeepSeekに入力したデータはどこに保存されますか？","a":"公式プライバシーポリシーによると、収集した情報は中華人民共和国にあるサーバーに保存されます。日本からは越境移転となるため、個人情報保護法上の対応が必要です。"},{"q":"企業でDeepSeekを使う際、何を確認すべきですか？","a":"利用規約でデータの学習利用の可否を確認し、可能ならオプトアウト設定を有効にします。加えて、API契約にデータ非利用条項を盛り込む、入力データの範囲を限定するなどの対策が有効です。"},{"q":"DeepSeekの学習データ利用はオフにできますか？","a":"Web版やアプリの設定画面から「モデル改善のためのデータ利用」をオフにできる場合があります。ただし、UI変更やバージョンにより異なるため、利用前に必ず最新設定を確認してください。"},{"q":"日本語の個人情報保護法との関係は？","a":"個人データを中国のサーバーへ提供する場合、個人情報保護法第28条に基づき、本人の同意または同等の措置が必要です。社内利用ではこの点を踏まえたリスク評価を行ってください。"}],
